-- Queravue seed for Oracle, mirroring seed/mssql. Runs once on a fresh volume.
-- Names are quoted lowercase so the shared enginetest suite finds them.
WHENEVER SQLERROR EXIT FAILURE
CONNECT queravue/queravue@//localhost:1521/FREEPDB1
SET DEFINE OFF

CREATE TABLE "customers" (
    "id" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" VARCHAR2(100) NOT NULL,
    "email" VARCHAR2(150) NOT NULL UNIQUE,
    "created_at" TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP
);
INSERT INTO "customers" ("name", "email") VALUES ('Alice Smith', 'alice@example.com');
INSERT INTO "customers" ("name", "email") VALUES ('Bob Jones', 'bob@example.com');
INSERT INTO "customers" ("name", "email") VALUES ('Charlie Brown', 'charlie@example.com');

CREATE TABLE "orders" (
    "id" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "customer_id" NUMBER(10) NOT NULL,
    "total_amount" NUMBER(10, 2) DEFAULT 0 NOT NULL,
    "created_at" TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP,
    CONSTRAINT "fk_orders_customer" FOREIGN KEY ("customer_id") REFERENCES "customers" ("id") ON DELETE CASCADE
);
INSERT INTO "orders" ("customer_id", "total_amount") VALUES (1, 149.99);
INSERT INTO "orders" ("customer_id", "total_amount") VALUES (1, 49.50);
INSERT INTO "orders" ("customer_id", "total_amount") VALUES (2, 299.00);

CREATE TABLE "order_items" (
    "order_id" NUMBER(10) NOT NULL,
    "item_id" NUMBER(10) NOT NULL,
    "product_name" CLOB NOT NULL,
    "quantity" NUMBER(10) DEFAULT 1 NOT NULL,
    "unit_price" NUMBER(10, 2) NOT NULL,
    PRIMARY KEY ("order_id", "item_id"),
    CONSTRAINT "fk_items_order" FOREIGN KEY ("order_id") REFERENCES "orders" ("id") ON DELETE CASCADE
);
INSERT INTO "order_items" VALUES (1, 1, 'Mechanical Keyboard', 1, 120.00);
INSERT INTO "order_items" VALUES (1, 2, 'Keycap Set', 1, 29.99);
INSERT INTO "order_items" VALUES (2, 1, 'Mousepad', 1, 49.50);
INSERT INTO "order_items" VALUES (3, 1, 'Monitor Stand', 1, 299.00);

CREATE TABLE "logs_no_pk" (
    "logged_at" TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP,
    "level" VARCHAR2(20) NOT NULL,
    "message" CLOB NOT NULL
);
INSERT INTO "logs_no_pk" ("level", "message") VALUES ('INFO', 'System started');
INSERT INTO "logs_no_pk" ("level", "message") VALUES ('WARN', 'High memory pressure');
INSERT INTO "logs_no_pk" ("level", "message") VALUES ('INFO', 'Backup completed');

CREATE VIEW "customer_order_summary_view" AS
SELECT c."id" AS "customer_id",
       c."name" AS "customer_name",
       COUNT(o."id") AS "total_orders",
       COALESCE(SUM(o."total_amount"), 0) AS "spent"
FROM "customers" c
LEFT JOIN "orders" o ON o."customer_id" = c."id"
GROUP BY c."id", c."name";

CREATE TABLE "пользователи" (
    "ид" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "имя" VARCHAR2(200) NOT NULL,
    "город" VARCHAR2(200)
);
INSERT INTO "пользователи" ("имя", "город") VALUES ('Олексій', 'Київ');
INSERT INTO "пользователи" ("имя", "город") VALUES ('Марія', 'Львів');

CREATE TABLE "type_samples" (
    "id" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "plain_number" NUMBER,
    "price" NUMBER(20, 4),
    "d" DATE,
    "ts" TIMESTAMP(6),
    "tstz" TIMESTAMP(3) WITH TIME ZONE,
    "tsltz" TIMESTAMP(3) WITH LOCAL TIME ZONE,
    "iv_ds" INTERVAL DAY(3) TO SECOND(3),
    "iv_ym" INTERVAL YEAR(3) TO MONTH,
    "big_text" CLOB,
    "big_ntext" NCLOB,
    "blob_data" BLOB,
    "raw_data" RAW(16),
    "bf" BINARY_FLOAT,
    "bd" BINARY_DOUBLE
);
INSERT INTO "type_samples" ("plain_number", "price", "d", "ts", "tstz", "tsltz", "iv_ds", "iv_ym", "big_text", "big_ntext", "blob_data", "raw_data", "bf", "bd")
VALUES (3.14159265358979323846, 12345678.9012, DATE '2026-01-02',
        TIMESTAMP '2026-01-02 03:04:05.678901', TIMESTAMP '2026-01-02 03:04:05.678 +02:00', TIMESTAMP '2026-01-02 03:04:05.678',
        INTERVAL '4 05:06:07.089' DAY TO SECOND, INTERVAL '2-3' YEAR TO MONTH,
        'placeholder', 'nclob text', HEXTORAW('00FF10'), HEXTORAW('123456789ABCDEF00123456789ABCDEF'), 1.5, 2.25);
INSERT INTO "type_samples" ("id") VALUES (2);
DECLARE
    text CLOB;
BEGIN
    FOR i IN 1 .. 10 LOOP
        text := text || RPAD('ж', 1000, 'ж');
    END LOOP;
    UPDATE "type_samples" SET "big_text" = text WHERE "id" = 1;
END;
/

CREATE TABLE "million_items" (
    "id" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "val" NUMBER(10) NOT NULL,
    "label" VARCHAR2(40) NOT NULL
);
INSERT /*+ APPEND */ INTO "million_items" ("val", "label")
SELECT LEVEL, 'item ' || LEVEL FROM dual CONNECT BY LEVEL <= 1000000;
COMMIT;
CREATE INDEX "idx_million_items_val" ON "million_items" ("val");

COMMIT;
BEGIN
    DBMS_STATS.GATHER_SCHEMA_STATS(USER);
END;
/
EXIT
